<?php
$all=projectList();$public=in_array($role,['public','resident'],true);$year=is_string($_GET['year']??null)?$_GET['year']:'';$category=is_string($_GET['category']??null)?$_GET['category']:'';$source=is_string($_GET['source']??null)?$_GET['source']:'';
$ps=array_values(array_filter($all,fn($p)=>($year==='' || substr($p['start_date'],0,4)===$year) && ($category==='' || (string)$p['category_id']===$category) && ($source==='' || (string)$p['source_id']===$source)));
$years=[];foreach($all as $p)$years[substr($p['start_date'],0,4)]=substr($p['start_date'],0,4);krsort($years);
$budget=array_sum(array_column($ps,'budget_cents'));$spentTotal=array_sum(array_column($ps,'spent'));$released=array_sum(array_column($ps,'released_cents'));
$counts=['Ongoing'=>0,'Completed'=>0,'Pending'=>0,'Cancelled'=>0];$categories=[];foreach($ps as $p){$counts[$p['status']]++;$categories[$p['category']]=($categories[$p['category']]??0)+(int)$p['budget_cents'];}
?>
<section class="panel"><form method="get" class="filters"><input type="hidden" name="page" value="<?= e($page) ?>"><?php selectField('Year','year',[''=>'All Years']+$years,$year,false);selectField('Category','category',[''=>'All Categories']+options('categories'),$category,false);selectField('Fund Source','source',[''=>'All Fund Sources']+options('fund_sources'),$source,false); ?><button>Apply</button><a class="button secondary" href="<?= e(url($page)) ?>">Reset</a><?php if($page==='reports'): ?><button type="button" data-print>Print / Save PDF</button><?php endif ?></form></section>
<div class="grid <?= $page==='reports'?'four':'three' ?> metrics"><?php if($page==='reports')metric('Total Projects',count($ps));metric('Allocated Fund',money($budget),'₱');metric('Spent',money($spentTotal),'₱');metric('Remaining Balance',money($budget-$spentTotal),'₱'); ?></div>
<?php if($page==='reports'): ?><div class="grid two"><?php chart($counts,'Project Status'); ?><section class="panel"><h2>Fund Allocation Overview</h2><?php barChart($categories); ?><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Category</th><th>Allocated Fund</th><th>Share</th></tr></thead><tbody><?php foreach($categories as $name=>$amount): ?><tr><td><?= e($name) ?></td><td><?= money($amount) ?></td><td><?= $budget?round($amount/$budget*100,1):0 ?>%</td></tr><?php endforeach;if(!$categories)emptyRow(3); ?></tbody></table></div></section></div><p class="note">Released fund: <?= money($released) ?> · Beneficiaries: <?= e(array_sum(array_column($ps,'beneficiary_count'))) ?>. Beneficiary totals are recorded counts and may include the same person in different projects.</p><?php endif ?>
<section class="panel"><h2>Project List / Financial Summary</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Project Name</th><th>Category</th><th>Year</th><th>Planned Amount</th><th>Approved Budget</th><th>Released Fund</th><th>Actual Spent</th><th>Remaining</th><th>Status</th></tr></thead><tbody><?php foreach($ps as $p): ?><tr><td><?= e($p['title']) ?></td><td><?= e($p['category']) ?></td><td><?= e(substr($p['start_date'],0,4)) ?></td><td><?= money($p['planned_cents']) ?></td><td><?= money($p['budget_cents']) ?></td><td><?= money($p['released_cents']) ?></td><td><?= money($p['spent']) ?></td><td><?= money($p['budget_cents']-$p['spent']) ?></td><td><?= badge($p['status']) ?></td></tr><?php endforeach;if(!$ps)emptyRow(9,'No matching records. Historical records appear here when entered; no years are deleted automatically.'); ?></tbody></table></div></section>
<?php if($page==='reports' && $role==='chairperson'): ?>
<section class="panel"><h2>Expense Records / Supporting Receipts</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Date</th><th>Project</th><th>Expense</th><th>Amount</th><th>Receipt</th></tr></thead><tbody><?php $selectedIds=array_column($ps,'id');$expenses=$selectedIds?rows('SELECT x.*,p.title FROM expenses x JOIN projects p ON p.id=x.project_id WHERE x.project_id IN ('.implode(',',array_fill(0,count($selectedIds),'?')).') ORDER BY x.expense_date DESC',$selectedIds):[];foreach($expenses as $x): ?><tr><td><?= e($x['expense_date']) ?></td><td><?= e($x['title']) ?></td><td><?= e($x['description']) ?></td><td><?= money($x['amount_cents']) ?></td><td><a href="<?= e(url('file',['kind'=>'receipt','id'=>$x['id']])) ?>" target="_blank" rel="noopener">View Receipt</a></td></tr><?php endforeach;if(!$expenses)emptyRow(5); ?></tbody></table></div></section>
<?php endif ?>
